/* ❌ OLD: The custom property has no registered syntax, so the browser
   treats it as an untyped token stream. Transitions/animations on it
   cannot interpolate — the value snaps from 0 to 200 with no smooth
   blend (50% is treated as an unparseable jump point). */

.card {
  --hue: 0; /* ❌ OLD: untyped token */
  transition: --hue 1s;
}

.card:hover {
  --hue: 200; /* ❌ OLD: no interpolation — discrete change */
}

/* The hue snaps instantly even though transition is declared, because
   the engine has no type information to blend 0 and 200. */

/* ✅ NEW: Registering the property with a syntax gives the engine type
   information, so --hue can be interpolated like a real number
   property: 0 -> 200 blends smoothly across the transition. */

@property --hue {
  syntax: '<number>'; /* ✅ NEW: typed as a number */
  inherits: false; /* ✅ NEW: don't leak into children */
  initial-value: 0; /* ✅ NEW: fallback for invalid/missing values */
}

.card {
  --hue: 0;
  transition: --hue 1s; /* ✅ NEW: now interpolates smoothly */
}

.card:hover {
  --hue: 200;
}

/* Invalid values are rejected (fall back to initial-value) instead of
   passing through as garbage tokens. */
